/**
 * Closes the HTTP/2 sessions tracked on the given server, if any.
 * Sessions keep the server open, so they must be closed for
 * `server.close()` to be able to complete.
 *
 * @param {object} server An HTTP/2 server instance created by
 * `getServerInstance`. Servers of any other kind are ignored.
 * @param {boolean} [destroy] When `true` the sessions are destroyed
 * instead of being gracefully closed.
 */
function closeHttp2Sessions (server, destroy) {
  const sessions = server[kHttp2Sessions]
  /* c8 ignore next 3 */
  if (sessions === undefined) {
    return
  }

  for (const session of sessions.values()) {
    if (destroy === true) {
      session.destroy()
    } else {
      session.close()
    }
  }
}

